{
    "metadata": {
        "name": "lb-vuln-bank",
        "namespace": "vuln-bank",
        "labels": {
            "ves.io/app_type": "ves-io-vuln-bank-lb-vuln-bank"
        },
        "annotations": {},
        "description": "https://github.com/Commando-X/vuln-bank",
        "disable": false
    },
    "spec": {
        "domains": [
            "{{vulnbank_base_url}}"
        ],
        "https_auto_cert": {
            "http_redirect": true,
            "add_hsts": true,
            "port": 443,
            "tls_config": {
                "default_security": {}
            },
            "no_mtls": {},
            "default_header": {},
            "enable_path_normalize": {},
            "non_default_loadbalancer": {},
            "header_transformation_type": {
                "legacy_header_transformation": {}
            },
            "connection_idle_timeout": 120000,
            "http_protocol_options": {
                "http_protocol_enable_v1_v2": {}
            },
            "coalescing_options": {
                "default_coalescing": {}
            }
        },
        "downstream_tls_certificate_expiration_timestamps": [
            {}
        ],
        "advertise_on_public_default_vip": {},
        "default_route_pools": [
            {
                "pool": {
                    "tenant": "{{xc_tenant_fullname}}",
                    "namespace": "vuln-bank",
                    "name": "origin-vuln-bank",
                    "kind": "origin_pool"
                },
                "weight": 1,
                "priority": 1,
                "endpoint_subsets": {}
            }
        ],
        "routes": [],
        "disable_caching": {},
        "app_firewall": {
            "tenant": "{{xc_tenant_fullname}}",
            "namespace": "vuln-bank",
            "name": "policy-vuln-bank",
            "kind": "app_firewall"
        },
        "add_location": true,
        "no_challenge": {},
        "user_id_client_ip": {},
        "disable_rate_limit": {},
        "waf_exclusion_rules": [],
        "waf_exclusion": {
            "waf_exclusion_inline_rules": {
                "rules": []
            }
        },
        "data_guard_rules": [],
        "blocked_clients": [],
        "trusted_clients": [],
        "ddos_mitigation_rules": [],
        "l7_ddos_protection": {
            "mitigation_block": {},
            "default_rps_threshold": {},
            "clientside_action_none": {},
            "ddos_policy_none": {}
        },
        "service_policies_from_namespace": {},
        "round_robin": {},
        "enable_trust_client_ip_headers": {
            "client_ip_headers": [
                "x-forwarded-for"
            ]
        },
        "disable_malicious_user_detection": {},
        "enable_api_discovery": {
            "disable_learn_from_redirect_traffic": {},
            "discovered_api_settings": {
                "purge_duration_for_inactive_discovered_apis": 7
            },
            "api_crawler": {
                "api_crawler_config": {
                    "domains": [
                        {
                            "domain": "{{vulnbank_base_url}}",
                            "simple_login": {
                                "user": "franklin",
                                "password": {
                                    "clear_secret_info": {
                                        "url": "string:///MTIzNDU2",
                                        "provider": ""
                                    },
                                    "secret_encoding_type": "EncodingNone"
                                }
                            }
                        }
                    ]
                }
            },
            "default_api_auth_discovery": {}
        },
        "bot_defense": {
            "regional_endpoint": "ASIA",
            "policy": {
                "protected_app_endpoints": [
                    {
                        "metadata": {
                            "name": "vulnbank-login",
                            "disable": false
                        },
                        "http_methods": [
                            "METHOD_POST"
                        ],
                        "flow_label": {
                            "authentication": {
                                "login": {
                                    "disable_transaction_result": {}
                                }
                            }
                        },
                        "protocol": "HTTPS",
                        "domain": {
                            "exact_value": "{{vulnbank_base_url}}"
                        },
                        "path": {
                            "path": "/login"
                        },
                        "query_params": [],
                        "headers": [],
                        "web_mobile": {
                            "header": {
                                "item": {
                                    "exact_values": [],
                                    "regex_values": [],
                                    "transformers": []
                                }
                            },
                            "headers": [],
                            "mobile_identifier": "HEADERS"
                        },
                        "mitigation": {
                            "flag": {
                                "no_headers": {}
                            }
                        },
                        "mitigate_good_bots": {}
                    }
                ],
                "js_insert_all_pages": {
                    "javascript_location": "AFTER_HEAD"
                },
                "js_download_path": "/common.js",
                "javascript_mode": "ASYNC_JS_CACHING",
                "mobile_sdk_config": {
                    "reload_header_name": "a877f745790",
                    "mobile_identifier": {
                        "headers": [
                            {
                                "name": "user-agent",
                                "item": {
                                    "exact_values": [
                                        "okhttp/4.12.0"
                                    ],
                                    "regex_values": [],
                                    "transformers": []
                                }
                            }
                        ]
                    }
                }
            },
            "timeout": 1000,
            "enable_cors_support": {}
        },
        "default_sensitive_data_policy": {},
        "api_testing": {
            "domains": [
                {
                    "domain": "{{vulnbank_base_url}}",
                    "allow_destructive_methods": false,
                    "credentials": [
                        {
                            "credential_name": "admin",
                            "login_endpoint": {
                                "path": "/login",
                                "method": "POST",
                                "json_payload": {
                                    "clear_secret_info": {
                                        "url": "string:///eyJ1c2VybmFtZSI6ImFkbWluIiwicGFzc3dvcmQiOiJhZG1pbjEyMyJ9",
                                        "provider": ""
                                    },
                                    "secret_encoding_type": "EncodingNone"
                                },
                                "token_response_key": "token"
                            },
                            "admin": {}
                        },
                        {
                            "credential_name": "franklin",
                            "login_endpoint": {
                                "path": "/login",
                                "method": "POST",
                                "json_payload": {
                                    "clear_secret_info": {
                                        "url": "string:///eyJ1c2VybmFtZSI6ImZyYW5rbGluIiwicGFzc3dvcmQiOiIxMjM0NTYifQ==",
                                        "provider": ""
                                    },
                                    "secret_encoding_type": "EncodingNone"
                                },
                                "token_response_key": "token"
                            },
                            "standard": {}
                        },
                        {
                            "credential_name": "john",
                            "login_endpoint": {
                                "path": "/login",
                                "method": "POST",
                                "json_payload": {
                                    "clear_secret_info": {
                                        "url": "string:///eyJ1c2VybmFtZSI6ImpvaG4iLCJwYXNzd29yZCI6IjEyMzQ1NiJ9",
                                        "provider": ""
                                    },
                                    "secret_encoding_type": "EncodingNone"
                                },
                                "token_response_key": "token"
                            },
                            "standard": {}
                        }
                    ]
                }
            ],
            "every_day": {},
            "custom_header_value": "x-f5-api-testing-identifier"
        },
        "disable_api_definition": {},
        "disable_ip_reputation": {},
        "disable_client_side_defense": {},
        "graphql_rules": [],
        "protected_cookies": [],
        "system_default_timeouts": {},
        "disable_threat_mesh": {},
        "disable_malware_protection": {}
    }
}
